import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { 
  Database, 
  HardDrive, 
  RefreshCw, 
  Trash2, 
  Download,
  Upload,
  CheckCircle,
  AlertTriangle,
  Info
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

function CacheManager({ onCacheUpdate }) {
  const { translate: t } = useLanguage();
  const [cacheInfo, setCacheInfo] = useState([]);
  const [totalSize, setTotalSize] = useState(0);
  const [loading, setLoading] = useState(false);
  const [storageQuota, setStorageQuota] = useState(null);

  useEffect(() => {
    loadCacheInfo();
    checkStorageQuota();
  }, []);

  const loadCacheInfo = async () => {
    setLoading(true);
    try {
      if ('caches' in window) {
        const cacheNames = await caches.keys();
        const cacheDetails = await Promise.all(
          cacheNames.map(async (name) => {
            const cache = await caches.open(name);
            const keys = await cache.keys();
            
            // Estimate cache size (rough calculation)
            let estimatedSize = 0;
            for (const request of keys.slice(0, 10)) { // Sample first 10 for performance
              try {
                const response = await cache.match(request);
                if (response) {
                  const blob = await response.blob();
                  estimatedSize += blob.size;
                }
              } catch (error) {
                // Skip failed requests
              }
            }
            
            // Extrapolate size for all items
            const avgSize = keys.length > 0 ? estimatedSize / Math.min(keys.length, 10) : 0;
            const totalEstimatedSize = avgSize * keys.length;
            
            return {
              name,
              count: keys.length,
              estimatedSize: totalEstimatedSize,
              type: getCacheType(name),
              lastUpdated: new Date() // This would ideally come from cache metadata
            };
          })
        );
        
        setCacheInfo(cacheDetails);
        setTotalSize(cacheDetails.reduce((sum, cache) => sum + cache.estimatedSize, 0));
      }
    } catch (error) {
      console.error('Error loading cache info:', error);
    } finally {
      setLoading(false);
    }
  };

  const checkStorageQuota = async () => {
    try {
      if ('storage' in navigator && 'estimate' in navigator.storage) {
        const estimate = await navigator.storage.estimate();
        setStorageQuota(estimate);
      }
    } catch (error) {
      console.error('Error checking storage quota:', error);
    }
  };

  const getCacheType = (cacheName) => {
    if (cacheName.includes('static') || cacheName.includes('asset')) return 'static';
    if (cacheName.includes('data') || cacheName.includes('api')) return 'data';
    if (cacheName.includes('offline')) return 'offline';
    return 'other';
  };

  const getCacheTypeIcon = (type) => {
    switch (type) {
      case 'static': return <HardDrive className="h-4 w-4" />;
      case 'data': return <Database className="h-4 w-4" />;
      case 'offline': return <Download className="h-4 w-4" />;
      default: return <Info className="h-4 w-4" />;
    }
  };

  const getCacheTypeColor = (type) => {
    switch (type) {
      case 'static': return 'bg-blue-500';
      case 'data': return 'bg-green-500';
      case 'offline': return 'bg-orange-500';
      default: return 'bg-gray-500';
    }
  };

  const formatSize = (bytes) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const clearSpecificCache = async (cacheName) => {
    try {
      await caches.delete(cacheName);
      await loadCacheInfo();
      onCacheUpdate?.();
      console.log(`Cache ${cacheName} cleared successfully`);
    } catch (error) {
      console.error(`Error clearing cache ${cacheName}:`, error);
    }
  };

  const clearAllCaches = async () => {
    try {
      const cacheNames = await caches.keys();
      await Promise.all(cacheNames.map(name => caches.delete(name)));
      await loadCacheInfo();
      onCacheUpdate?.();
      console.log('All caches cleared successfully');
    } catch (error) {
      console.error('Error clearing all caches:', error);
    }
  };

  const refreshCache = async (cacheName) => {
    try {
      // This would trigger a cache refresh by re-fetching resources
      const cache = await caches.open(cacheName);
      const keys = await cache.keys();
      
      // Re-fetch a sample of resources to refresh the cache
      const sampleKeys = keys.slice(0, 5);
      await Promise.all(
        sampleKeys.map(async (request) => {
          try {
            const response = await fetch(request.url);
            if (response.ok) {
              await cache.put(request, response);
            }
          } catch (error) {
            console.warn(`Failed to refresh ${request.url}:`, error);
          }
        })
      );
      
      await loadCacheInfo();
      onCacheUpdate?.();
      console.log(`Cache ${cacheName} refreshed`);
    } catch (error) {
      console.error(`Error refreshing cache ${cacheName}:`, error);
    }
  };

  const getStorageUsagePercentage = () => {
    if (!storageQuota || !storageQuota.quota) return 0;
    return Math.round((storageQuota.usage / storageQuota.quota) * 100);
  };

  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Database className="h-5 w-5" />
          {t('إدارة التخزين المؤقت')}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Storage Quota Information */}
        {storageQuota && (
          <div className="space-y-2">
            <div className="flex justify-between items-center text-sm">
              <span>{t('استخدام التخزين')}</span>
              <span>{formatSize(storageQuota.usage)} / {formatSize(storageQuota.quota)}</span>
            </div>
            <Progress value={getStorageUsagePercentage()} className="h-2" />
            <div className="text-xs text-gray-600 text-center">
              {getStorageUsagePercentage()}% {t('مستخدم')}
            </div>
          </div>
        )}

        {/* Cache Summary */}
        <div className="grid grid-cols-2 gap-4">
          <div className="text-center p-3 bg-gray-50 rounded-lg">
            <div className="text-2xl font-bold text-orange-600">{cacheInfo.length}</div>
            <div className="text-sm text-gray-600">{t('ذاكرة التخزين المؤقت')}</div>
          </div>
          <div className="text-center p-3 bg-gray-50 rounded-lg">
            <div className="text-2xl font-bold text-orange-600">{formatSize(totalSize)}</div>
            <div className="text-sm text-gray-600">{t('الحجم الإجمالي')}</div>
          </div>
        </div>

        {/* Global Actions */}
        <div className="flex gap-2">
          <Button
            onClick={loadCacheInfo}
            disabled={loading}
            variant="outline"
            className="flex-1"
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
            {t('تحديث')}
          </Button>
          <Button
            onClick={clearAllCaches}
            variant="destructive"
            className="flex-1"
          >
            <Trash2 className="h-4 w-4 mr-2" />
            {t('مسح الكل')}
          </Button>
        </div>

        {/* Cache Details */}
        <div className="space-y-3">
          <h4 className="font-medium text-sm">{t('تفاصيل التخزين المؤقت')}</h4>
          {cacheInfo.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              <Database className="h-12 w-12 mx-auto mb-2 opacity-50" />
              <p>{t('لا توجد ذاكرة تخزين مؤقت')}</p>
            </div>
          ) : (
            cacheInfo.map((cache) => (
              <Card key={cache.name} className="border-l-4" style={{ borderLeftColor: getCacheTypeColor(cache.type).replace('bg-', '#') }}>
                <CardContent className="p-4">
                  <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center gap-2">
                      {getCacheTypeIcon(cache.type)}
                      <span className="font-medium text-sm">{cache.name}</span>
                    </div>
                    <Badge variant="secondary" className="text-xs">
                      {cache.type}
                    </Badge>
                  </div>
                  
                  <div className="grid grid-cols-2 gap-4 text-xs text-gray-600 mb-3">
                    <div>
                      <span className="font-medium">{t('العناصر')}: </span>
                      {cache.count}
                    </div>
                    <div>
                      <span className="font-medium">{t('الحجم')}: </span>
                      {formatSize(cache.estimatedSize)}
                    </div>
                  </div>
                  
                  <div className="flex gap-2">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => refreshCache(cache.name)}
                      className="flex-1 text-xs"
                    >
                      <RefreshCw className="h-3 w-3 mr-1" />
                      {t('تحديث')}
                    </Button>
                    <Button
                      size="sm"
                      variant="destructive"
                      onClick={() => clearSpecificCache(cache.name)}
                      className="flex-1 text-xs"
                    >
                      <Trash2 className="h-3 w-3 mr-1" />
                      {t('مسح')}
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>

        {/* Cache Health Indicators */}
        <div className="space-y-2">
          <h4 className="font-medium text-sm">{t('حالة التخزين المؤقت')}</h4>
          <div className="grid grid-cols-1 gap-2">
            <div className="flex items-center gap-2 p-2 bg-green-50 rounded">
              <CheckCircle className="h-4 w-4 text-green-600" />
              <span className="text-sm text-green-800">
                {t('التخزين المؤقت يعمل بشكل طبيعي')}
              </span>
            </div>
            
            {totalSize > 50 * 1024 * 1024 && ( // 50MB threshold
              <div className="flex items-center gap-2 p-2 bg-yellow-50 rounded">
                <AlertTriangle className="h-4 w-4 text-yellow-600" />
                <span className="text-sm text-yellow-800">
                  {t('حجم التخزين المؤقت كبير - قد تحتاج إلى التنظيف')}
                </span>
              </div>
            )}
            
            {storageQuota && getStorageUsagePercentage() > 80 && (
              <div className="flex items-center gap-2 p-2 bg-red-50 rounded">
                <AlertTriangle className="h-4 w-4 text-red-600" />
                <span className="text-sm text-red-800">
                  {t('مساحة التخزين منخفضة')}
                </span>
              </div>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

export default CacheManager;
